// Search queries on MyJobMag, each mapped to the CV role it targets.
// (Exact title queries are kept for future posts; broad queries catch current ones.)
const terms = [
  { role: 'ai-workflow-engineer', term: 'AI Workflow Engineer' },
  { role: 'n8n-automation-specialist', term: 'n8n Automation Specialist' },
  { role: 'n8n-automation-specialist', term: 'workflow automation' },
  { role: 'llm-application-developer', term: 'LLM Application Developer' },
  { role: 'ai-automation-engineer', term: 'AI automation' },
  { role: 'ai-automation-engineer', term: 'AI Automation Engineer' },
  { role: 'ai-agent-developer', term: 'AI Agent Developer' },
  { role: 'software-developer', term: 'Software Developer' },
];

return terms.map((t) => ({
  json: {
    role: t.role,
    term: t.term,
    url: 'https://www.myjobmag.co.ke/search/jobs?q=' + encodeURIComponent(t.term),
  },
}));

const fs = require('fs');
const path = require('path');
const DATA_DIR = 'C:/Users/osage/OneDrive/Documents/Projects/Reasonix/jobhunter/data';
const LEDGER = path.join(DATA_DIR, 'applications.json');

let ledger = [];
if (fs.existsSync(LEDGER)) {
  try { ledger = JSON.parse(fs.readFileSync(LEDGER, 'utf8')); } catch (e) { ledger = []; }
}
const seen = new Set(ledger.map((j) => j.url));

const termsNode = $('Generate Search Terms');
const items = $input.all();
const jobs = [];
for (const it of items) {
  const pi = it.pairedItem?.item ?? 0;
  let role = termsNode.item(pi).json.role;
  let term = termsNode.item(pi).json.term;
  const json = it.json;
  const html = typeof json.body === 'string' ? json.body : JSON.stringify(json.body ?? '');
  if (json.error) { console.log('search failed for', term, json.error); continue; }
  const re = /<h2><a href="(\/job\/[^"]+)">([^<]+)<\/a><\/h2>/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    const url = 'https://www.myjobmag.co.ke' + m[1];
    if (seen.has(url)) continue;
    const title = m[2].trim();
    const companyMatch = title.match(/\s+at\s+(.+)$/i);
    const company = companyMatch ? companyMatch[1].trim() : '';
    const cleanTitle = companyMatch ? title.slice(0, title.length - companyMatch[0].length) : title;
    seen.add(url);
    jobs.push({ json: { role, term, title: cleanTitle, company, url, date: new Date().toISOString().slice(0, 10) } });
  }
}
return jobs;

