const fs = require('fs');
const path = require('path');
const DATA_DIR = 'C:/Users/osage/OneDrive/Documents/Projects/Reasonix/jobhunter/data';
const LEDGER = path.join(DATA_DIR, 'applications.json');

const items = $input.all().map((it) => it.json);
const now = new Date().toISOString();

// persist all new jobs to the local ledger (source of truth until Google Sheets is enabled)
let ledger = [];
if (fs.existsSync(LEDGER)) {
  try { ledger = JSON.parse(fs.readFileSync(LEDGER, 'utf8')); } catch (e) { ledger = []; }
}
for (const job of items) {
  if (!ledger.some((l) => l.url === job.url)) {
    ledger.push({ ...job, id: 'JOB-' + String(Date.now()).slice(-6) + '-' + ledger.length, foundAt: now, status: 'found' });
  }
}
fs.writeFileSync(LEDGER, JSON.stringify(ledger, null, 2));

const count = items.length;
let msg = '';
if (count === 0) {
  msg = 'Internship check \u2014 no new matching jobs found today. ' + ledger.length + ' tracked in total.';
} else {
  msg = 'Internship check \u2014 found ' + count + ' new job' + (count > 1 ? 's' : '') + '!\n' +
    items.slice(0, 5).map((j) => '\u2022 ' + j.roleLabel + ' @ ' + (j.company || j.title)).join('\n') +
    (count > 5 ? '\n...and ' + (count - 5) + ' more.' : '');
}
return [{ json: { msg, newJobs: count, ledgerTotal: ledger.length } }];
